void FindMaximum(int a, int b, int c)
{
    int max;
    if (a > b) max = a; else max = b;
    if (c > max) max = c;
    cout << "Max = " << max << endl;
}
int main()
{
    int x, y, z;
    cin >> x >> y >> z;
    FindMaximum(x, y, z);
    return 0;
}

int FindMaximum(int a, int b, int c)
{
    int max;
    if (a > b) max = a; else max = b;
    if (c > max) max = c;
    return max;
}
int main()
{
    int x, y, z;
    cin >> x >> y >> z;
    cout << "Max = " << FindMaximum(x, y, z) << endl;
    return 0;
}

