#include <iostream>
using namespace std;
void calculateSum()
{
    int a = 5;          // локальные переменные подпрограммы
    int b = 10;
    int sum = a + b;
    cout << "Sum of " << sum << endl;
}
int main()
{
    int x = 100;        // локальная переменная main
    cout << "Value of x in main: " << x << endl;
    calculateSum();
    return 0;
}

int fact(int n)
{
    int result = 1;
    for (int i = 1; i <= n; ++i)
        result *= i;
    return result;
}
int main()
{
    int num;
    cout << "Введите число : ";
    cin >> num;
    cout << "Факториал = " << fact(num);
    return 0;
}

bool prost(int n)
{
    if (n <= 1) return false;          // числа <= 1 не простые
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) return false;  // делится на i — не простое
    return true;
}
int main()
{
    int num;
    cin >> num;
    if (prost(num)) cout << num << " — простое число." << endl;
    else cout << num << " — не простое число." << endl;
    return 0;
}

int sumArray(int arr[], int size)
{
    int sum = 0;
    for (int i = 0; i < size; i++)
        sum += arr[i];
    return sum;
}

int FindMaximum(int a, int b)
{
    if (a > b) return a;
    else return b;
}
int main()
{
    int x, y, z, v;
    cin >> x >> y >> z >> v;
    cout << "Max = " << FindMaximum(FindMaximum(FindMaximum(x, y), z), v) << endl;
    return 0;
}

